functions._tiSlug:
function _tiSlug(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 30);
}

// 2026-05-23: detect a paragraph that's effectively just template logic
// — strip every {{...}} and [[...]] block plus whitespace/punctuation,
// and check if anything meaningful remains. True for paragraphs like
// "{{IF supplier_type == 'vendor'}}", "[[FOR each]]", "{{ENDIF}}" etc.
// These shouldn't be auto-bookmarked; admin can manually un-skip if they
// really want a bookmark on a control-flow paragraph.

functions._tiIsLogicOnly:
function _tiIsLogicOnly(text) {
  if (!text) return true;
  var stripped = String(text)
    .replace(/\{\{[\s\S]*?\}\}/g, "")
    .replace(/\[\[[\s\S]*?\]\]/g, "")
    .replace(/[\s.,;:!?\-_—–'"`]/g, "");
  return stripped.length === 0;
}

// 2026-05-23: bookmark naming. Word requires names to start with a letter
// (per CLAUDE.md anti-pattern: leading underscore → silent no-op) and
// caps length around 40 chars. Encodes both number and title in the
// name so admin / Office.js can see them via the Bookmark dialog —
// number-first because that's the navigation key admins think in.
// existing: { name: true } map of names already taken in this batch.

functions._tiBookmarkName:
function _tiBookmarkName(number, title, parentArticleNumber, existing) {
  existing = existing || {};
  // 2026-05-23: when section has no own number but lives under a parent
  // article that does (e.g. "Liability Cap" under Article 1), prefix with
  // the parent's number so the bookmark name reflects the document
  // structure: ELI_SEC_1_liability_cap, not ELI_SEC_liability_cap.
  var effectiveNumber = number || parentArticleNumber || "";
  var numSlug = String(effectiveNumber).replace(/[^a-zA-Z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  var titleSlug = _tiSlug(title);
  var base = "ELI_SEC_";
  if (numSlug) base += numSlug + "_";
  base += titleSlug || "untitled";
  // 40-char cap (Word limit)
  base = base.slice(0, 38);
  var name = base;
  var n = 2;
  while (existing[name]) {
    name = base.slice(0, 36) + "-" + n;
    if (name.length > 40) name = name.slice(0, 40);
    n++;
  }
  existing[name] = true;
  return name;
}

functions._tiScanSections:
function _tiScanSections() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.readStructuralMap !== "function") {
    return Promise.reject(new Error("eli.host.readStructuralMap unavailable"));
  }
  return window.eli.host.readStructuralMap({ anchors: false }).then(function (map) {
    if (!map || !Array.isArray(map.headers)) {
      return { headers: [], paragraphCount: 0 };
    }
    var existing = {};
    // 2026-05-23: pre-pass to compute parent article for each header.
    // Walk through headers in order. For each header at level N, parent
    // article is the most recent prior header at level < N. Carries
    // {number, title, level} so downstream rendering and bookmark naming
    // can prefix with parent context (e.g. unnumbered "Liability Cap"
    // under Article 1 → ELI_SEC_1_liability_cap + "↳ Article 1" badge).
    var _kernelHeaders = map.headers;
    // 2026-05-23 BUG FIX: original walk-by-level grabbed any lower-level
    // header as the parent, which incorrectly tagged "Definitions" as
    // belonging to "Recitals" when the doc structure was actually:
    //   RECITALS (level 0)
    //   ARTICLE 1 — DEFINITIONS (level 1)
    //   "Liability Cap" (level 2)
    // Recitals isn't an Article — it's a top-level non-Article header.
    // New rules:
    //   1. If current section's number is dotted (5.1.2), parent is the
    //      header with the prefix number (5.1) — exact number lookup.
    //   2. Otherwise, walk back to the nearest ARTICLE HEADER specifically
    //      (matches "Article N" pattern OR single-integer number ≤ 99).
    //      Skip non-Article headers like Recitals on the way back.
    function _isArticleHeader(h) {
      if (!h) return false;
      var title = String(h.title || h.text || "").trim();
      if (/^\s*Article\b/i.test(title)) return true;
      var num = String(h.number || "").trim();
      if (!num || num === "[Unnumbered]") return false;
      var cleanNum = num.replace(/[.\)\:]+$/, "");
      if (/^\d+$/.test(cleanNum) && Number(cleanNum) <= 99) return true;
      return false;
    }
    // 2026-05-23: exhibit-style container headers (Exhibit A, Schedule 1,
    // Appendix B, Annex II). Treated as valid parent containers — sections
    // detected AFTER an exhibit header belong to that exhibit (until the
    // next exhibit or until admin manually changes the parent).
    function _isExhibitHeader(h) {
      if (!h) return false;
      var title = String(h.title || h.text || "").trim();
      return /^\s*(Exhibit|Appendix|Schedule|Annex)\b/i.test(title);
    }
    function _isContainerHeader(h) {
      return _isArticleHeader(h) || _isExhibitHeader(h);
    }
    function _isExcludedFromParenting(h) {
      var title = String(h.title || h.text || "").trim().toLowerCase();
      return /^\s*(recitals?|whereas|witnesseth|preamble|now,?\s+therefore)\b/.test(title);
    }
    function _cleanHeader(h) {
      var n = String(h.number || "").trim();
      if (n === "[Unnumbered]") n = "";
      if (n) n = n.replace(/[.\)\:]+$/, "");
      var t = String(h.title || h.text || "").trim();
      if (!n) {
        var mm = t.match(/^\s*(\d+(?:\.\d+)*)[\.\)\s]+(.+)$/);
        if (mm) { n = mm[1]; t = mm[2].trim(); }
      }
      // 2026-05-23: when this is an exhibit-style header and the number
      // is still empty, parse "Exhibit A — Schedule of Fees" → number=A,
      // title="Schedule of Fees" so bookmark names + parent inheritance
      // work with the exhibit designator (ELI_SEC_A_payment_terms).
      if (!n) {
        var em = t.match(/^\s*(?:Exhibit|Appendix|Schedule|Annex)\s+([A-Z0-9]+)\s*[—\-:.\s]*(.*)$/i);
        if (em) { n = em[1]; t = (em[2] || "").trim() || t; }
      }
      return { number: n, title: t, level: h.level || 0 };
    }
    function _parentForHeader(currentIdx) {
      var h = _kernelHeaders[currentIdx];
      var current = _cleanHeader(h);
      var currentLevel = h.level || 0;
      // Top-level Article/Exhibit headers have no parent.
      if (_isContainerHeader(h) && (!current.number || current.number.indexOf(".") === -1)) return null;
      // Strategy 1: dotted number ("5.1.2") → look up prefix ("5.1") directly.
      if (current.number && current.number.indexOf(".") !== -1) {
        var parentNum = current.number.split(".").slice(0, -1).join(".");
        for (var j = currentIdx - 1; j >= 0; j--) {
          var pj = _cleanHeader(_kernelHeaders[j]);
          if (pj.number === parentNum) return pj;
        }
      }
      // Strategy 2: walk back; accept first header that is either
      //   - a Container header (Article/Exhibit) — strong parent signal
      //   - OR strictly lower level than current (hierarchy signal)
      // Skip explicit non-parent headers (Recitals, Preamble, etc.) on
      // the way back so they're never returned as parents.
      for (var k = currentIdx - 1; k >= 0; k--) {
        var prev = _kernelHeaders[k];
        if (_isExcludedFromParenting(prev)) continue;
        if (_isContainerHeader(prev)) {
          return _cleanHeader(prev);
        }
        var prevLevel = prev.level || 0;
        if (currentLevel > 0 && prevLevel < currentLevel) {
          return _cleanHeader(prev);
        }
      }
      return null;
    }
    // 2026-05-23: full ancestry chain — walk parent → parent → root.
    // [{ number: "3", title: "Article 3" }, { number: "3.3", title: "..." }]
    // ordered from top-level Article down to immediate parent.
    function _ancestryForHeader(currentIdx) {
      var chain = [];
      var p = _parentForHeader(currentIdx);
      var seenIdx = currentIdx;
      var guard = 0;
      while (p && guard++ < 10) {
        chain.unshift(p);
        // Walk up by finding which header in _kernelHeaders matches p
        var foundIdx = -1;
        for (var i = seenIdx - 1; i >= 0; i--) {
          var c = _cleanHeader(_kernelHeaders[i]);
          if (c.number === p.number && c.title === p.title) { foundIdx = i; break; }
        }
        if (foundIdx === -1) break;
        seenIdx = foundIdx;
        p = _parentForHeader(foundIdx);
      }
      return chain;
    }
    var headers = map.headers.map(function (h, hIdx) {
      var num = String(h.number || "").trim();
      if (num === "[Unnumbered]") num = "";
      var ttl = String(h.title || h.text || "").trim();
      // Detection sometimes lumps the number into the title (e.g.,
      // "5.1 Limitation of Liability"). Split if number's missing AND
      // title leads with a dotted-digit sequence.
      if (!num) {
        var m = ttl.match(/^\s*(\d+(?:\.\d+)*)[\.\)\s]+(.+)$/);
        if (m) { num = m[1]; ttl = m[2].trim(); }
      }
      // 2026-05-23: definitions truncation. Defined terms typically open
      // with a quoted phrase ("Liability Cap" means the maximum amount…)
      // but the whole paragraph gets pulled in as the heading text by
      // the detector. Truncate the title at the matching closing quote
      // so just the defined term is the section name. Handles straight
      // " and curly “”/‘’ quote pairs.
      var QUOTE_CLOSE = { '"': '"', '“': '”', '‘': '’', "'": "'" };
      var firstCh = ttl.charAt(0);
      if (QUOTE_CLOSE.hasOwnProperty(firstCh)) {
        var closeCh = QUOTE_CLOSE[firstCh];
        var closeIdx = ttl.indexOf(closeCh, 1);
        if (closeIdx > 0) ttl = ttl.slice(0, closeIdx + 1);
      }
      var parentArticle = _parentForHeader(hIdx);
      var ancestry = _ancestryForHeader(hIdx);
      // 2026-05-23: detect logic-only headers (paragraph is just
      // {{...}} / [[...]] markers). Per user, NOT auto-skipped — admin
      // decides manually. LOGIC chip stays visible so admin can spot
      // them at a glance.
      var rawText = String(h.text || h.title || "").trim();
      var isLogicOnly = _tiIsLogicOnly(rawText);
      return {
        paragraphIdx: h.idx,
        number: num,
        title: ttl || "(untitled)",
        level: h.level || 0,
        parentArticle: parentArticle,
        ancestry: ancestry,
        originalNumber: num,
        originalTitle: ttl,
        bookmarkName: _tiBookmarkName(num, ttl, parentArticle && parentArticle.number, existing),
        skip: false,
        logicOnly: isLogicOnly,
        edited: false,
      };
    });
    // 2026-05-23: auto-prepend Preamble. The kernel's detector only
    // surfaces header paragraphs; the body text before the first header
    // (title, parties block, recitals, "NOW, THEREFORE…") has no
    // section. Add a virtual "Preamble" header at paragraph 0 so search
    // hits in this region get a real section label + Locate works.
    // Admin can rename, edit number, or skip this row like any other.
    if (headers.length > 0 && headers[0].paragraphIdx > 0) {
      // 2026-05-23: skip auto-prepend if every paragraph before the first
      // header is logic-only. No point in bookmarking a "Preamble" that
      // contains nothing but {{IF}} / [[FOR]] control flow.
      var hasRealPreambleContent = false;
      if (map.paragraphs && Array.isArray(map.paragraphs)) {
        for (var pi = 0; pi < map.paragraphs.length; pi++) {
          var prow = map.paragraphs[pi];
          if (!prow || prow.idx >= headers[0].paragraphIdx) break;
          if (!_tiIsLogicOnly(prow.text || "")) {
            hasRealPreambleContent = true;
            break;
          }
        }
      } else {
        hasRealPreambleContent = true; // can't tell — default to including
      }
      if (hasRealPreambleContent) {
        var preExisting = {};
        headers.forEach(function (h) { preExisting[h.bookmarkName] = true; });
        var preBookmarkName = _tiBookmarkName("", "preamble", null, preExisting);
        headers.unshift({
          paragraphIdx: 0,
          number: "",
          title: "Preamble",
          level: 0,
          parentArticle: null,
          ancestry: [],
          originalNumber: "",
          originalTitle: "Preamble",
          bookmarkName: preBookmarkName,
          skip: false,
          logicOnly: false,
          edited: false,
          autoPrepended: true,
        });
      }
    }
    // 2026-05-23 (Phase B+C): also pass through every paragraph for the
    // "show all paragraphs" view + range grouping. Each entry carries
    // idx, plain text (truncated for preview), isHeader flag, and the
    // logic-only flag so the per-paragraph UI can render efficiently.
    var paragraphsAll = (map.paragraphs || []).map(function (p) {
      var t = String(p.text || "");
      return {
        idx: p.idx,
        text: t,
        preview: t.length > 120 ? t.slice(0, 117) + "…" : t,
        isHeader: !!p.isHeader,
        logicOnly: _tiIsLogicOnly(t),
      };
    });
    return {
      headers: headers,
      paragraphs: paragraphsAll,
      paragraphCount: map.paragraphCount || 0,
    };
  });
}

// Write bookmarks via Word.run. Two modes:
//   smart (default) — diff existing ELI_SEC_* bookmarks against the
//     active set. Leave matching ones alone, insert only new names,
//     delete only orphans. Cheap for incremental re-indexes after small
//     structural changes (admin renamed one section, added one new).
//   force — clear every ELI_SEC_* and write all fresh. Used by the
//     "Clear & Restart" path when admin wants a true reset.

functions._tiApplyBookmarks:
function _tiApplyBookmarks(sections, opts) {
  opts = opts || {};
  var force = !!opts.force;
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  var active = sections.filter(function (s) { return !s.skip && s.bookmarkName; });
  if (!active.length) return Promise.resolve({ written: 0, cleared: 0, kept: 0 });
  return window.eli.host.runRaw("template_indexer.apply", function (ctx) {
    var bookmarks = ctx.document.bookmarks;
    bookmarks.load("items/name");
    var paragraphs = ctx.document.body.paragraphs;
    paragraphs.load("items/text");
    return ctx.sync().then(function () {
      var existingByName = {};
      bookmarks.items.forEach(function (bm) {
        if (bm.name && bm.name.indexOf("ELI_SEC_") === 0) existingByName[bm.name] = bm;
      });
      var desiredByName = {};
      active.forEach(function (s) { desiredByName[s.bookmarkName] = s; });
      // 2026-05-23: capture per-bookmark action so the UI can show admin
      // exactly what changed (which bookmarks got written/kept/removed
      // by name). Powers the post-Apply details panel.
      var actionLog = { written: [], kept: [], cleared: [] };
      if (force) {
        Object.keys(existingByName).forEach(function (name) {
          try { existingByName[name].delete(); actionLog.cleared.push(name); } catch (_e) {}
        });
      } else {
        Object.keys(existingByName).forEach(function (name) {
          if (!desiredByName[name]) {
            try { existingByName[name].delete(); actionLog.cleared.push(name); } catch (_e) {}
          } else {
            actionLog.kept.push(name);
          }
        });
      }
      var paraCount = paragraphs.items.length;
      active.forEach(function (s) {
        if (!force && existingByName[s.bookmarkName]) return;
        if (s.paragraphIdx < 0 || s.paragraphIdx >= paraCount) return;
        var p = paragraphs.items[s.paragraphIdx];
        try {
          // 2026-05-23 (Phase C): manual sections get RANGE bookmarks
          // spanning from first paragraph's start to last paragraph's end.
          // Detected sections still get point bookmarks at the start —
          // their coverage is implicit (until next section bookmark).
          if (s.isManual && typeof s.endParagraphIdx === "number" &&
              s.endParagraphIdx >= s.paragraphIdx && s.endParagraphIdx < paraCount) {
            var lastP = paragraphs.items[s.endParagraphIdx];
            var range = p.getRange("Start").expandTo(lastP.getRange("End"));
            range.insertBookmark(s.bookmarkName);
          } else {
            p.getRange("Start").insertBookmark(s.bookmarkName);
          }
          actionLog.written.push(s.bookmarkName);
        } catch (_e) {}
      });
      return ctx.sync().then(function () {
        return {
          written: actionLog.written.length,
          cleared: actionLog.cleared.length,
          kept: actionLog.kept.length,
          actions: actionLog,
        };
      });
    });
  });
}

functions._tiRenderRow:
function _tiRenderRow(s, idx, nextStartIdx, totalParagraphs) {
  var disabledCls = s.skip ? " _ti_row_skipped" : "";
  var bookmarkPreview = s.skip
    ? '<span style="color:#94a3b8;font-style:italic;">(skipped)</span>'
    : '<code class="_ti_bookmark_name">' + _tiEsc(s.bookmarkName) + '</code>';
  // 2026-05-23: pip now reads "L1"/"L2" instead of just "1"/"2" so it's
  // self-evident as a heading level. Same color coding by level.
  var levelLabel = "L" + (s.level || 0);
  var levelPip = '<span class="_ti_level_pip _ti_level_pip_' + (s.level || 0) + '" title="Heading level ' + (s.level || 0) + ' — 1=top (Article), 2=sub-section, 3=sub-sub, etc.">' + levelLabel + '</span>';
  // 2026-05-23: parent article badge — shows "↳ Article N — Title" when
  // this section lives under a higher-level header. Drives the user's
  // mental model that unnumbered subsections still inherit their parent.
  var parentBadge = "";
  // 2026-05-23: detect Exhibit-vs-Article for nicer labels in the
  // ancestry chain. An ancestor whose title leads with Exhibit/Schedule/
  // Appendix/Annex gets that prefix; otherwise it's an Article.
  function _ancestorLabel(a, isFirst) {
    if (!a) return "";
    var rawTitle = String(a.title || "");
    var typeMatch = rawTitle.match(/^\s*(Exhibit|Appendix|Schedule|Annex)\b/i);
    var num = a.number || "";
    if (typeMatch) {
      // Title already starts with the type — just use the title verbatim
      // (e.g. "Exhibit A — Schedule of Fees" stays whole).
      return rawTitle;
    }
    if (num && isFirst) return "Article " + num + (rawTitle ? " " + rawTitle : "");
    if (num) return num + (rawTitle ? " " + rawTitle : "");
    return rawTitle;
  }
  if (s.ancestry && s.ancestry.length) {
    var chainHtml = s.ancestry.map(function (a, i) {
      return '<span class="_ti_anc_link">' + _tiEsc(_ancestorLabel(a, i === 0)) + '</span>';
    }).join('<span class="_ti_anc_sep"> › </span>');
    parentBadge = '<div class="_ti_parent_article" title="Document hierarchy — full ancestry chain from top-level container down to immediate parent">↳ ' + chainHtml + '</div>';
  } else if (s.parentArticle) {
    var pLabel = _ancestorLabel(s.parentArticle, true);
    parentBadge = '<div class="_ti_parent_article" title="Section lives under this parent header in the document structure">↳ ' + _tiEsc(pLabel) + '</div>';
  }
  // 2026-05-23: paragraph range — makes the section\'s coverage explicit
  // so admin doesn\'t think paragraphs between section starts are being
  // skipped. They\'re body content of the section above.
  var endIdx = (typeof nextStartIdx === "number" ? nextStartIdx - 1 : totalParagraphs - 1);
  var paraRange = s.paragraphIdx === endIdx
    ? "paragraph " + s.paragraphIdx
    : "spans paragraphs " + s.paragraphIdx + "–" + endIdx;
  var logicBadge = s.logicOnly
    ? '<span class="_ti_logic_chip" title="Paragraph contains only template logic ({{...}} / [[...]]) — uncheck the box to skip if you don\'t want a bookmark here.">LOGIC</span>'
    : '';
  var manualBadge = s.isManual
    ? '<span class="_ti_manual_chip" title="Admin-created manual section — uses a range bookmark spanning paragraphs ' + s.paragraphIdx + '–' + s.endParagraphIdx + '">MANUAL</span>'
    : '';
  return '<div class="_ti_row' + disabledCls + (s.logicOnly ? ' _ti_row_logic' : '') + '" data-idx="' + idx + '">' +
    '<input type="checkbox" class="_ti_row_skip" data-act="toggle-skip" data-idx="' + idx + '"' + (s.skip ? "" : " checked") + ' title="' + (s.logicOnly ? "Auto-skipped: logic-only paragraph. Check the box if you want a bookmark here anyway." : "Uncheck to skip this section") + '">' +
    levelPip +
    '<div class="_ti_row_main">' +
      (parentBadge || logicBadge || manualBadge ? '<div class="_ti_parent_row">' + parentBadge + (logicBadge ? ' ' + logicBadge : '') + (manualBadge ? ' ' + manualBadge : '') + '</div>' : '') +
      '<div class="_ti_row_heading">' +
        '<div class="_ti_field_group">' +
          '<label class="_ti_field_label">Number</label>' +
          '<input type="text" class="_ti_input _ti_input_number" data-act="edit-number" data-idx="' + idx + '" value="' + _tiEsc(s.number) + '" placeholder="(none)" title="Section number — e.g. 5.1 — leave blank if unnumbered">' +
        '</div>' +
        '<div class="_ti_field_group">' +
          '<label class="_ti_field_label">Title</label>' +
          '<input type="text" class="_ti_input _ti_input_title" data-act="edit-title" data-idx="' + idx + '" value="' + _tiEsc(s.title) + '" placeholder="Section title" title="Section title">' +
        '</div>' +
      '</div>' +
      '<div class="_ti_row_meta">' +
        '<span class="_ti_meta_label">Bookmark (auto):</span> ' + bookmarkPreview +
        ' <span class="_ti_row_meta_dim">· ' + _tiEsc(paraRange) + '</span>' +
        ' <button class="_ti_row_locate" data-act="locate-row" data-idx="' + idx + '" title="Jump to this section in the open Word document">📍 Locate</button>' +
      '</div>' +
    '</div>' +
  '</div>';
}

// 2026-05-23: clear all ELI_SEC_* bookmarks from the open doc — wipes
// the doc's index without re-applying. Used by "Clear & Restart" to
// give admin a clean slate. Returns {cleared: N} on success.

functions._tiClearAllBookmarks:
function _tiClearAllBookmarks() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  return window.eli.host.runRaw("template_indexer.clear", function (ctx) {
    var bookmarks = ctx.document.bookmarks;
    bookmarks.load("items/name");
    return ctx.sync().then(function () {
      var cleared = 0;
      bookmarks.items.forEach(function (bm) {
        if (bm.name && bm.name.indexOf("ELI_SEC_") === 0) {
          try { bm.delete(); cleared++; } catch (_e) { /* tolerate */ }
        }
      });
      return ctx.sync().then(function () { return { cleared: cleared }; });
    });
  });
}

// 2026-05-23: Locate handler for indexer row. Selects + scrolls to the
// section's paragraph via Word.run. Lets admin verify each detected
// section is the right paragraph before applying bookmarks.

functions._tiLocateParagraph:
function _tiLocateParagraph(paragraphIdx) {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("Word host not available", "err");
    return;
  }
  window.eli.host.runRaw("template_indexer.locate", function (ctx) {
    var paragraphs = ctx.document.body.paragraphs;
    ctx.load(paragraphs, "items");
    return ctx.sync().then(function () {
      if (paragraphIdx < 0 || paragraphIdx >= paragraphs.items.length) {
        throw new Error("paragraph_out_of_range");
      }
      paragraphs.items[paragraphIdx].select();
      return ctx.sync();
    });
  }).then(function () {
    if (typeof showToast === "function") {
      showToast("✓ Selected paragraph " + paragraphIdx + " in document", "ok");
    }
  }).catch(function (err) {
    if (typeof showToast === "function") {
      showToast("Locate failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

functions.showTemplateIndexer:
function showTemplateIndexer() {
  var out = window.eli && window.eli.ui && window.eli.ui.claimOutput
    ? window.eli.ui.claimOutput()
    : document.getElementById("output");
  if (!out) return;
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ti_root">' +
      '<div class="_ti_header">' +
        '<div>' +
          '<div class="_ti_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ti_header_title">🔖 Template Indexer</div>' +
          '<div class="_ti_header_sub" id="_ti_status">Scanning current document…</div>' +
        '</div>' +
        '<div class="_ti_header_btns">' +
          '<button class="_ti_btn _ti_btn_danger" id="_ti_clear_restart" title="Delete every ELI_SEC_* bookmark from the open doc AND re-run detection from scratch">🗑 Clear &amp; Restart</button>' +
          '<button class="_ti_btn _ti_btn_platinum" id="_ti_rescan" title="Re-run section detection without touching existing bookmarks">↻ Re-scan</button>' +
          '<button class="_ti_btn _ti_btn_gold" id="_ti_apply" disabled>🔖 Apply Bookmarks</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ti_explainer">' +
        '<b>Workflow:</b> Open the finalized template in Word → click <b>Apply Bookmarks</b> here → save the doc → re-upload via <b>Template Manager</b>. ' +
        'Bookmarks travel with the file; downstream tools (template_searcher, etc.) will use them for section-aware navigation.' +
      '</div>' +
      '<div class="_ti_body" id="_ti_body">' +
        '<div class="_ti_loading"><span class="_ti_spinner"></span>Reading section structure from <code>eli.host.readStructuralMap</code>…</div>' +
      '</div>' +
    '</div>';
  var state = {
    sections: [],         // detected sections + admin-created manual sections
    paragraphs: [],       // every paragraph in the doc (for show-all view)
    selectedParagraphs: {}, // { paragraphIdx: true } for multi-select
    lastSelectedIdx: null,// for shift-click range selection
    showAllParagraphs: false,
    scannedAt: 0,
    paragraphCount: 0,
  };
  var bodyEl = out.querySelector("#_ti_body");
  var statusEl = out.querySelector("#_ti_status");
  var applyBtn = out.querySelector("#_ti_apply");
  var rescanBtn = out.querySelector("#_ti_rescan");
  function _renderBody() {
    if (!state.sections.length) {
      bodyEl.innerHTML = '<div class="_ti_empty">' +
        '<div class="_ti_empty_icon">∅</div>' +
        '<div class="_ti_empty_title">No sections detected</div>' +
        '<div class="_ti_empty_sub">The current document has no headings recognizable to <code>readStructuralMap</code>. ' +
        'Use Word\'s Heading 1/2/3 styles, numbered lists, or ALL-CAPS short paragraphs to mark sections.</div>' +
      '</div>';
      applyBtn.disabled = true;
      return;
    }
    var activeCount = state.sections.filter(function (s) { return !s.skip; }).length;
    var manualCount = state.sections.filter(function (s) { return s.isManual; }).length;
    bodyEl.innerHTML =
      '<div class="_ti_summary">' +
        '<span class="_ti_summary_count">' + activeCount + '</span> ' +
        ' of ' + state.sections.length + ' sections will be bookmarked' +
        (manualCount ? ' · <span class="_ti_summary_manual">' + manualCount + ' manual</span>' : '') + '. ' +
        'Edit numbers / titles below if needed; uncheck to skip.' +
      '</div>' +
      '<div class="_ti_list">' +
        state.sections.map(function (s, i) {
          var next = (i + 1 < state.sections.length) ? state.sections[i + 1].paragraphIdx : null;
          return _tiRenderRow(s, i, next, state.paragraphCount);
        }).join("") +
      '</div>' +
      _renderShowAllParagraphsPanel();
    applyBtn.disabled = activeCount === 0;
  }
  // 2026-05-23 (Phase B+C): show-all-paragraphs panel. Renders flat list
  // of every paragraph with checkbox + idx + preview + current section
  // assignment. Multi-select via checkboxes; sticky action bar shows
  // "Group as new section" when ≥2 paragraphs selected.
  function _renderShowAllParagraphsPanel() {
    if (!state.paragraphs || !state.paragraphs.length) return "";
    var openAttr = state.showAllParagraphs ? " open" : "";
    var selectedCount = Object.keys(state.selectedParagraphs).length;
    return '<details class="_ti_all_paragraphs"' + openAttr + '>' +
      '<summary class="_ti_all_paragraphs_summary" data-act="toggle-all-paragraphs">' +
        '📜 Show all paragraphs (' + state.paragraphs.length + ')' +
        ' — for fine-tuning section boundaries or creating manual sections' +
      '</summary>' +
      '<div class="_ti_all_paragraphs_body">' +
        '<div class="_ti_all_paragraphs_help">' +
          'Each row shows the paragraph and its <strong>current section assignment</strong> ' +
          '(computed from the nearest preceding bookmark). ' +
          'Select multiple paragraphs and click <strong>Group as section</strong> to create a new section ' +
          'spanning the selection — useful when the kernel missed a section entirely (e.g. Exhibit B with no header).' +
        '</div>' +
        '<div class="_ti_para_list">' +
          state.paragraphs.map(_tiRenderParagraphRow).join("") +
        '</div>' +
        (selectedCount >= 1
          ? '<div class="_ti_sticky_action">' +
              '<span><b>' + selectedCount + '</b> paragraph' + (selectedCount === 1 ? '' : 's') + ' selected</span>' +
              '<div class="_ti_sticky_buttons">' +
                '<button class="_ti_btn _ti_btn_platinum" data-act="clear-selection">Clear</button>' +
                '<button class="_ti_btn _ti_btn_gold" data-act="group-selection"' + (selectedCount < 1 ? ' disabled' : '') + '>📦 Group as new section</button>' +
              '</div>' +
            '</div>'
          : '') +
      '</div>' +
    '</details>';
  }
  function _tiRenderParagraphRow(p) {
    var checked = state.selectedParagraphs[p.idx] ? " checked" : "";
    var selectedCls = state.selectedParagraphs[p.idx] ? " _ti_para_row_selected" : "";
    // Current section assignment — walk backward through sections to
    // find the most recent one whose paragraphIdx ≤ this paragraph.
    var assignment = null;
    for (var i = state.sections.length - 1; i >= 0; i--) {
      var s = state.sections[i];
      if (s.skip) continue;
      var sStart = s.paragraphIdx;
      var sEnd = (s.isManual && typeof s.endParagraphIdx === "number") ? s.endParagraphIdx :
                 ((i + 1 < state.sections.length) ? (state.sections[i + 1].paragraphIdx - 1) : (state.paragraphCount - 1));
      if (p.idx >= sStart && p.idx <= sEnd) { assignment = s; break; }
    }
    var assignmentLabel = assignment
      ? (assignment.number ? assignment.number + " " : "") + (assignment.title || assignment.bookmarkName)
      : "(no section)";
    var assignmentBadge = assignment
      ? '<span class="_ti_para_assignment' + (assignment.isManual ? ' _ti_para_assignment_manual' : '') + '" title="Section: ' + _tiEsc(assignment.bookmarkName) + '">' +
          _tiEsc(assignmentLabel) +
        '</span>'
      : '<span class="_ti_para_assignment _ti_para_assignment_none">(no section)</span>';
    var headerBadge = p.isHeader ? '<span class="_ti_para_header_chip" title="Detected as a header">H</span>' : '';
    var logicBadge = p.logicOnly ? '<span class="_ti_logic_chip">LOGIC</span>' : '';
    return '<div class="_ti_para_row' + selectedCls + (p.logicOnly ? ' _ti_para_row_logic' : '') + '" data-pidx="' + p.idx + '">' +
      '<input type="checkbox" class="_ti_para_checkbox" data-act="toggle-para" data-pidx="' + p.idx + '"' + checked + '>' +
      '<span class="_ti_para_idx">' + p.idx + '</span>' +
      headerBadge +
      logicBadge +
      '<span class="_ti_para_preview" title="' + _tiEsc(p.text || "") + '">' + _tiEsc(p.preview || "(empty)") + '</span>' +
      assignmentBadge +
    '</div>';
  }
  function _setStatus(text) { statusEl.textContent = text; }
  function _scan() {
    _setStatus("Scanning current document…");
    bodyEl.innerHTML = '<div class="_ti_loading"><span class="_ti_spinner"></span>Reading section structure…</div>';
    applyBtn.disabled = true;
    _tiScanSections().then(function (r) {
      state.sections = r.headers || [];
      state.paragraphs = r.paragraphs || [];
      state.selectedParagraphs = {};
      state.lastSelectedIdx = null;
      state.scannedAt = Date.now();
      state.paragraphCount = r.paragraphCount || 0;
      _setStatus("Detected " + state.sections.length + " section" + (state.sections.length === 1 ? "" : "s") +
        " across " + r.paragraphCount + " paragraph" + (r.paragraphCount === 1 ? "" : "s") + ".");
      _renderBody();
    }).catch(function (err) {
      _setStatus("Scan failed: " + (err && err.message || "unknown"));
      bodyEl.innerHTML = '<div class="_ti_empty">' +
        '<div class="_ti_empty_icon">⚠️</div>' +
        '<div class="_ti_empty_title">Couldn\'t read section structure</div>' +
        '<div class="_ti_empty_sub">' + _tiEsc(err && err.message || "unknown") + '</div>' +
      '</div>';
    });
  }
  // Recompute bookmark name when number/title edited. Keeps the per-batch
  // name uniqueness map fresh: rebuilds from all currently-active rows.
  function _refreshBookmarkNames() {
    var existing = {};
    state.sections.forEach(function (s) {
      if (s.skip) return;
      s.bookmarkName = _tiBookmarkName(
        s.number, s.title,
        s.parentArticle && s.parentArticle.number,
        existing
      );
    });
  }
  // 2026-05-23: render an expandable details panel under the toast that
  // lists each bookmark by name + action. Replaces previous panel each
  // time Apply fires; auto-collapses after 12s but stays in DOM so admin
  // can re-expand from <summary>.
  function _renderApplyDetails(actions) {
    var existing = out.querySelector("#_ti_apply_details");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    var written = (actions && actions.written) || [];
    var kept = (actions && actions.kept) || [];
    var cleared = (actions && actions.cleared) || [];
    if (!written.length && !kept.length && !cleared.length) return;
    function _list(label, names, color) {
      if (!names.length) return '';
      return '<div class="_ti_apply_group">' +
        '<div class="_ti_apply_group_head" style="color:' + color + ';">' +
          label + ' (' + names.length + ')' +
        '</div>' +
        '<div class="_ti_apply_group_body">' +
          names.map(function (n) {
            return '<code class="_ti_bookmark_name">' + _tiEsc(n) + '</code>';
          }).join(' ') +
        '</div>' +
      '</div>';
    }
    var html = '<details class="_ti_apply_details" id="_ti_apply_details" open>' +
      '<summary class="_ti_apply_summary">' +
        '📋 Smart Apply details (click to collapse)' +
      '</summary>' +
      '<div class="_ti_apply_body">' +
        _list("✓ Written (new bookmarks)", written, "#0f766e") +
        _list("· Kept (already matched)", kept, "#475569") +
        _list("✕ Cleared (orphans removed)", cleared, "#b91c1c") +
      '</div>' +
    '</details>';
    bodyEl.insertAdjacentHTML("afterbegin", html);
    // Auto-collapse after 12s so it doesn't permanently consume vertical space.
    setTimeout(function () {
      var el = out.querySelector("#_ti_apply_details");
      if (el && el.open) el.open = false;
    }, 12000);
  }
  rescanBtn.onclick = _scan;
  var clearRestartBtn = out.querySelector("#_ti_clear_restart");
  if (clearRestartBtn) {
    clearRestartBtn.onclick = function () {
      // No confirm dialog — destructive intent is in the button label,
      // and the action is reversible (admin can re-apply at any time).
      if (typeof showToast === "function") showToast("⏳ Clearing bookmarks…", "info");
      clearRestartBtn.disabled = true;
      _tiClearAllBookmarks().then(function (r) {
        if (typeof showToast === "function") {
          showToast("🗑 Cleared " + r.cleared + " bookmark" + (r.cleared === 1 ? "" : "s") + ". Re-detecting…", "info");
        }
        _scan();
      }).catch(function (err) {
        if (typeof showToast === "function") {
          showToast("Clear failed: " + (err && err.message || "unknown"), "err");
        }
      }).then(function () {
        clearRestartBtn.disabled = false;
      });
    };
  }
  applyBtn.onclick = function () {
    if (!state.sections.length) return;
    var active = state.sections.filter(function (s) { return !s.skip; });
    if (!active.length) return;
    if (typeof showToast === "function") showToast("⏳ Writing " + active.length + " bookmarks…", "info");
    applyBtn.disabled = true;
    _tiApplyBookmarks(state.sections).then(function (r) {
      applyBtn.disabled = false;
      if (typeof showToast === "function") {
        var parts = [];
        if (r.written) parts.push("wrote " + r.written);
        if (r.kept) parts.push("kept " + r.kept + " unchanged");
        if (r.cleared) parts.push("removed " + r.cleared + " orphan" + (r.cleared === 1 ? "" : "s"));
        var summary = parts.length ? parts.join(", ") : "no changes";
        showToast("✓ Smart Apply: " + summary +
          ". Save the doc + re-upload via Build Draft.", "ok");
      }
      _setStatus("Applied at " + new Date().toLocaleTimeString() +
        " · " + r.written + " written · " + (r.kept || 0) + " kept · " + r.cleared + " cleared. Save + upload to persist.");
      // 2026-05-23: render per-bookmark details panel — admin sees
      // exactly which bookmark names were written / kept / removed.
      _renderApplyDetails(r.actions || {});
    }).catch(function (err) {
      applyBtn.disabled = false;
      if (typeof showToast === "function") {
        showToast("Apply failed: " + (err && err.message || "unknown"), "err");
      }
    });
  };
  // Click delegation for skip toggle + input edits
  out.onclick = function (ev) {
    var t = ev.target;
    if (!t || !t.getAttribute) return;
    var act = t.getAttribute("data-act");
    if (act === "toggle-skip") {
      var idx = Number(t.getAttribute("data-idx"));
      var s = state.sections[idx];
      if (s) {
        s.skip = !t.checked;
        _refreshBookmarkNames();
        _renderBody();
      }
    }
    if (act === "locate-row") {
      var lidx = Number(t.getAttribute("data-idx"));
      var ls = state.sections[lidx];
      if (ls) _tiLocateParagraph(ls.paragraphIdx);
    }
    // 2026-05-23 (Phase B+C): show-all-paragraphs interactions.
    if (act === "toggle-all-paragraphs") {
      state.showAllParagraphs = !state.showAllParagraphs;
      // Browser handles details toggle natively; we only mirror state.
    }
    if (act === "toggle-para") {
      var pidx = Number(t.getAttribute("data-pidx"));
      var shiftKey = !!(ev.shiftKey);
      if (shiftKey && state.lastSelectedIdx !== null) {
        // Range select from lastSelectedIdx to pidx (inclusive).
        var lo = Math.min(state.lastSelectedIdx, pidx);
        var hi = Math.max(state.lastSelectedIdx, pidx);
        var willSelect = !!t.checked;
        state.paragraphs.forEach(function (pp) {
          if (pp.idx >= lo && pp.idx <= hi) {
            if (willSelect) state.selectedParagraphs[pp.idx] = true;
            else delete state.selectedParagraphs[pp.idx];
          }
        });
      } else {
        if (t.checked) state.selectedParagraphs[pidx] = true;
        else delete state.selectedParagraphs[pidx];
        state.lastSelectedIdx = pidx;
      }
      _refreshAllParagraphsView();
    }
    if (act === "clear-selection") {
      state.selectedParagraphs = {};
      state.lastSelectedIdx = null;
      _refreshAllParagraphsView();
    }
    if (act === "group-selection") {
      _showGroupDialog();
    }
  };
  // Re-render just the paragraph panel (keep section list above intact).
  function _refreshAllParagraphsView() {
    var panel = out.querySelector("._ti_all_paragraphs");
    if (!panel) return;
    var wasOpen = panel.open;
    var newHtml = _renderShowAllParagraphsPanel();
    var wrapper = document.createElement("div");
    wrapper.innerHTML = newHtml;
    var newPanel = wrapper.firstChild;
    if (newPanel) {
      newPanel.open = wasOpen || state.showAllParagraphs;
      panel.parentNode.replaceChild(newPanel, panel);
    }
  }
  // 2026-05-23 (Phase C): Group Selection dialog. Captures number + title
  // from admin, creates a manual section spanning the selected paragraphs.
  function _showGroupDialog() {
    var sel = Object.keys(state.selectedParagraphs).map(Number).sort(function (a, b) { return a - b; });
    if (!sel.length) {
      if (typeof showToast === "function") showToast("Select at least one paragraph first", "warn");
      return;
    }
    var firstIdx = sel[0];
    var lastIdx = sel[sel.length - 1];
    var firstPara = state.paragraphs.filter(function (p) { return p.idx === firstIdx; })[0];
    var defaultTitle = firstPara ? firstPara.preview.slice(0, 50).replace(/[\.\-—:].*$/, "").trim() : "";
    var DIALOG_ID = "_ti_group_dialog_" + Date.now();
    var overlay = document.createElement("div");
    overlay.id = DIALOG_ID;
    overlay.style.cssText =
      "position:fixed;top:80px;left:50%;transform:translateX(-50%);" +
      "width:480px;max-width:95vw;" +
      "background:#fff;border:1px solid #cbd5e1;border-radius:8px;" +
      "box-shadow:0 12px 40px rgba(15,23,42,0.25);" +
      "z-index:1100;display:flex;flex-direction:column;";
    overlay.innerHTML =
      '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);color:#fff;padding:12px 16px;border-bottom:2px solid #c9a227;border-radius:7px 7px 0 0;">' +
        '<div style="font:800 9px/1 Inter,sans-serif;letter-spacing:1.4px;text-transform:uppercase;color:#c9a227;margin-bottom:3px;">CREATE MANUAL SECTION</div>' +
        '<div style="font:700 16px/1.2 \'Book Antiqua\',Georgia,serif;">📦 Group ' + sel.length + ' paragraph' + (sel.length === 1 ? '' : 's') + ' into a new section</div>' +
      '</div>' +
      '<div style="padding:16px;">' +
        '<div style="font-size:11px;color:#475569;margin-bottom:12px;">' +
          'Paragraphs <b>' + firstIdx + '</b>–<b>' + lastIdx + '</b> will be bookmarked as a range. ' +
          'The bookmark spans the entire selection so downstream tools recognize the section ' +
          'even though no header demarcates it.' +
        '</div>' +
        '<div style="margin-bottom:10px;">' +
          '<label style="font:700 9.5px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#94a3b8;display:block;margin-bottom:4px;">Number (e.g. B, 1, 5.2)</label>' +
          '<input type="text" id="' + DIALOG_ID + '_num" placeholder="(leave blank if unnumbered)" style="width:100%;padding:8px;font:600 12px/1.3 ui-monospace,Consolas,monospace;border:1px solid #cbd5e1;border-radius:4px;box-sizing:border-box;">' +
        '</div>' +
        '<div style="margin-bottom:14px;">' +
          '<label style="font:700 9.5px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#94a3b8;display:block;margin-bottom:4px;">Title</label>' +
          '<input type="text" id="' + DIALOG_ID + '_ttl" placeholder="e.g. Schedule of Fees" value="' + _tiEsc(defaultTitle) + '" style="width:100%;padding:8px;font:600 13px/1.3 Inter,sans-serif;border:1px solid #cbd5e1;border-radius:4px;box-sizing:border-box;">' +
        '</div>' +
        '<div style="font-size:10px;color:#94a3b8;margin-bottom:12px;">' +
          'Bookmark name preview: <code id="' + DIALOG_ID + '_preview" style="font-family:Monaco,monospace;background:#dbeafe;color:#1e40af;padding:2px 6px;border-radius:3px;">ELI_SEC_…</code>' +
        '</div>' +
        '<div style="display:flex;gap:8px;justify-content:flex-end;">' +
          '<button data-act="group-cancel" style="padding:8px 14px;font:700 10px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;background:#fff;color:#475569;border:1px solid #cbd5e1;border-radius:4px;cursor:pointer;">Cancel</button>' +
          '<button data-act="group-confirm" style="padding:8px 16px;font:800 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;background:linear-gradient(180deg,#d4af37 0%,#c9a227 100%);color:#0d1b2a;border:none;border-radius:4px;cursor:pointer;">📦 Create Section</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(overlay);
    var numInp = overlay.querySelector("#" + DIALOG_ID + "_num");
    var ttlInp = overlay.querySelector("#" + DIALOG_ID + "_ttl");
    var previewEl = overlay.querySelector("#" + DIALOG_ID + "_preview");
    function _updatePreview() {
      var existing = {};
      state.sections.forEach(function (s) { if (s.bookmarkName) existing[s.bookmarkName] = true; });
      var name = _tiBookmarkName(numInp.value.trim(), ttlInp.value.trim(), null, existing);
      previewEl.textContent = name;
    }
    numInp.oninput = _updatePreview;
    ttlInp.oninput = _updatePreview;
    _updatePreview();
    setTimeout(function () { try { ttlInp.focus(); ttlInp.select(); } catch (_) {} }, 50);
    overlay.addEventListener("click", function (ev2) {
      var btn = ev2.target.closest && ev2.target.closest("button[data-act]");
      if (!btn) return;
      var act2 = btn.getAttribute("data-act");
      if (act2 === "group-cancel") {
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        return;
      }
      if (act2 === "group-confirm") {
        var num = numInp.value.trim();
        var ttl = ttlInp.value.trim() || "Manual Section";
        var existing = {};
        state.sections.forEach(function (s) { if (s.bookmarkName) existing[s.bookmarkName] = true; });
        var bookmarkName = _tiBookmarkName(num, ttl, null, existing);
        var newSection = {
          paragraphIdx: firstIdx,
          endParagraphIdx: lastIdx,
          number: num,
          title: ttl,
          level: 1,
          parentArticle: null,
          ancestry: [],
          originalNumber: num,
          originalTitle: ttl,
          bookmarkName: bookmarkName,
          skip: false,
          logicOnly: false,
          edited: false,
          isManual: true,
        };
        // Insert in correct position (sorted by paragraphIdx).
        var inserted = false;
        for (var i = 0; i < state.sections.length; i++) {
          if (state.sections[i].paragraphIdx > firstIdx) {
            state.sections.splice(i, 0, newSection);
            inserted = true;
            break;
          }
        }
        if (!inserted) state.sections.push(newSection);
        state.selectedParagraphs = {};
        state.lastSelectedIdx = null;
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        if (typeof showToast === "function") showToast("✓ Manual section created — click Apply to write the range bookmark", "ok");
        _renderBody();
      }
    });
    // Esc to close
    overlay.addEventListener("keydown", function (ev2) {
      if (ev2.key === "Escape" && overlay.parentNode) overlay.parentNode.removeChild(overlay);
    });
  }
  out.oninput = function (ev) {
    var t = ev.target;
    if (!t || !t.getAttribute) return;
    var act = t.getAttribute("data-act");
    var idx = Number(t.getAttribute("data-idx"));
    var s = state.sections[idx];
    if (!s) return;
    if (act === "edit-number") {
      s.number = String(t.value || "").trim();
      s.edited = true;
    } else if (act === "edit-title") {
      s.title = String(t.value || "").trim();
      s.edited = true;
    } else {
      return;
    }
    _refreshBookmarkNames();
    // Update only the bookmark-name preview cell, not the whole list —
    // preserves the input focus + caret position so admin can keep typing.
    var row = out.querySelector('._ti_row[data-idx="' + idx + '"] ._ti_row_meta');
    if (row) {
      var preview = s.skip
        ? '<span style="color:#94a3b8;font-style:italic;">(skipped)</span>'
        : '<code class="_ti_bookmark_name">' + _tiEsc(s.bookmarkName) + '</code>';
      var next = (idx + 1 < state.sections.length) ? state.sections[idx + 1].paragraphIdx : null;
      var endIdx = (next != null ? next - 1 : state.paragraphCount - 1);
      var paraRange = s.paragraphIdx === endIdx
        ? "paragraph " + s.paragraphIdx
        : "spans paragraphs " + s.paragraphIdx + "–" + endIdx;
      row.innerHTML = '<span class="_ti_meta_label">Bookmark (auto):</span> ' + preview +
        ' <span class="_ti_row_meta_dim">· ' + _tiEsc(paraRange) + '</span>' +
        ' <button class="_ti_row_locate" data-act="locate-row" data-idx="' + idx + '" title="Jump to this section in the open Word document">📍 Locate</button>';
    }
  };
  _scan();
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;
  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateIndexer"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showTemplateIndexer !== "function") {
      eli.log.event("tool", "template_indexer_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Indexer failed to load", "err");
      return;
    }
    try { window.showTemplateIndexer(); }
    catch (e) {
      eli.log.event("tool", "template_indexer_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }
  eli.register({
    tile: { app_template_indexer: _show },
    template_indexer: { open: _show },
  });
  eli.log.event("tool", "template_indexer_initialized", {});
}

jsonTools.css:
/* template_indexer — premium admin UI matching template_searcher's palette.
   Class prefix `_ti_`. Single accent: gold #c9a227. */

._ti_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0 0 32px 0;
  min-height: 100vh;
  box-sizing: border-box;
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._ti_root),
.output-area:has(> ._ti_root) {
  background: #f8fafc !important;
}

._ti_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 20px 24px;
  border-bottom: 3px solid #c9a227;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
._ti_header_eyebrow {
  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 6px;
}
._ti_header_title {
  font: 800 24px/1.1 "Book Antiqua", Georgia, serif;
  margin: 0;
}
._ti_header_sub {
  font-size: 11px;
  color: rgba(255,255,255,0.72);
  margin-top: 6px;
  font-weight: 500;
}
._ti_header_btns { display: flex; gap: 8px; }
._ti_btn {
  padding: 9px 14px;
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  border-radius: 4px;
  transition: filter 0.15s, transform 0.05s;
}
._ti_btn:active { transform: translateY(1px); }
._ti_btn:disabled { opacity: 0.45; cursor: not-allowed; }
._ti_btn_platinum {
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  color: #334155;
  border: 1px solid #cbd5e1;
}
._ti_btn_platinum:hover:not(:disabled) { filter: brightness(0.97); }
._ti_btn_gold {
  background: linear-gradient(180deg, #d4af37 0%, #c9a227 100%);
  color: #0d1b2a;
  font-weight: 800;
  box-shadow: 0 1px 0 rgba(0,0,0,0.06);
}
._ti_btn_gold:hover:not(:disabled) { filter: brightness(1.04); }
._ti_btn_danger {
  background: linear-gradient(180deg, #fef2f2 0%, #fee2e2 100%);
  color: #991b1b;
  border: 1px solid #fca5a5;
}
._ti_btn_danger:hover:not(:disabled) { filter: brightness(0.97); background: linear-gradient(180deg, #fee2e2 0%, #fecaca 100%); }

._ti_explainer {
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 6px;
  margin: 16px 18px 0 18px;
  padding: 12px 14px;
  font-size: 12px;
  color: #78350f;
  line-height: 1.5;
}
._ti_explainer b { color: #422006; }

._ti_body { margin: 18px; }

._ti_loading {
  padding: 28px 24px;
  text-align: center;
  font-size: 12px;
  color: #64748b;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._ti_loading code {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 10.5px;
  color: #475569;
  background: #f1f5f9;
  padding: 1px 5px;
  border-radius: 3px;
}
._ti_spinner {
  display: inline-block;
  width: 12px; height: 12px;
  border: 2px solid #e2e8f0;
  border-top-color: #c9a227;
  border-radius: 50%;
  animation: _ti_spin 0.8s linear infinite;
  margin-right: 8px;
  vertical-align: middle;
}
@keyframes _ti_spin { to { transform: rotate(360deg); } }

._ti_empty {
  padding: 40px 24px;
  text-align: center;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._ti_empty_icon { font-size: 40px; margin-bottom: 10px; opacity: 0.85; }
._ti_empty_title { font: 700 15px/1.3 "Book Antiqua", Georgia, serif; color: #0f172a; margin-bottom: 6px; }
._ti_empty_sub { font-size: 11px; color: #64748b; max-width: 520px; margin: 0 auto; }
._ti_empty code { font-family: ui-monospace, Consolas, monospace; background: #f1f5f9; padding: 1px 5px; border-radius: 3px; }

._ti_summary {
  font: 600 12px/1.4 Inter, sans-serif;
  color: #475569;
  margin-bottom: 12px;
  padding: 10px 14px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  border-radius: 4px;
}
._ti_summary_count {
  font-weight: 800;
  color: #0f172a;
  font-size: 14px;
}

._ti_list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

._ti_row {
  display: grid;
  grid-template-columns: 24px 34px 1fr;
  gap: 10px;
  align-items: start;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 5px;
  transition: border-color 0.12s, background 0.12s;
}
._ti_row:hover { border-color: #cbd5e1; }
._ti_row_skipped {
  background: #fafbfc;
  opacity: 0.55;
}
._ti_row_skip {
  width: 16px; height: 16px;
  cursor: pointer;
  accent-color: #c9a227;
}

._ti_level_pip {
  width: 30px; height: 22px;
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.3px;
  color: #fff;
  flex-shrink: 0;
}
._ti_level_pip_0 { background: #94a3b8; }
._ti_level_pip_1 { background: #1565c0; }
._ti_level_pip_2 { background: #0891b2; }
._ti_level_pip_3 { background: #059669; }
._ti_level_pip_4 { background: #65a30d; }
._ti_level_pip_5 { background: #a16207; }
._ti_level_pip_6 { background: #b45309; }
._ti_level_pip_7 { background: #b91c1c; }
._ti_level_pip_8, ._ti_level_pip_9 { background: #6b21a8; }

._ti_row_main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._ti_parent_row {
  margin-bottom: 2px;
}
._ti_parent_article {
  font: 700 9.5px/1.4 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #5b21b6;
  background: #ede9fe;
  padding: 3px 8px;
  border-radius: 3px;
  border: 1px dashed #c4b5fd;
  display: inline-block;
}
._ti_anc_link { color: #5b21b6; }
._ti_anc_sep { color: #a78bfa; padding: 0 2px; }

._ti_logic_chip {
  font: 700 9px/1.4 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: #b45309;
  background: #fef3c7;
  padding: 2px 7px;
  border-radius: 3px;
  border: 1px dashed #fbbf24;
  display: inline-block;
}
._ti_row_logic {
  background: #fafaf8;
  opacity: 0.7;
}

._ti_apply_details {
  background: #fff;
  border: 1px solid #c9a227;
  border-radius: 6px;
  margin-bottom: 12px;
  box-shadow: 0 1px 4px rgba(201, 162, 39, 0.12);
}
._ti_apply_summary {
  cursor: pointer;
  padding: 10px 14px;
  font: 700 11px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #422006;
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 100%);
  border-radius: 6px;
  list-style: none;
  user-select: none;
}
._ti_apply_summary::-webkit-details-marker { display: none; }
._ti_apply_summary::marker { content: ""; }
._ti_apply_details[open] > ._ti_apply_summary {
  border-radius: 6px 6px 0 0;
  border-bottom: 1px solid #fde68a;
}
._ti_apply_body {
  padding: 10px 14px;
}
._ti_apply_group { margin-bottom: 10px; }
._ti_apply_group:last-child { margin-bottom: 0; }
._ti_apply_group_head {
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin-bottom: 6px;
}
._ti_apply_group_body {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

._ti_manual_chip {
  font: 700 9px/1.4 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: #1e40af;
  background: #dbeafe;
  padding: 2px 7px;
  border-radius: 3px;
  border: 1px dashed #93c5fd;
  display: inline-block;
}
._ti_summary_manual {
  color: #1e40af;
  font-weight: 800;
}

._ti_all_paragraphs {
  margin-top: 16px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  overflow: hidden;
}
._ti_all_paragraphs_summary {
  cursor: pointer;
  user-select: none;
  padding: 12px 14px;
  font: 700 12px/1 Inter, sans-serif;
  letter-spacing: 0.3px;
  color: #0f172a;
  background: linear-gradient(180deg, #fafbfc 0%, #f1f5f9 100%);
  list-style: none;
}
._ti_all_paragraphs_summary::-webkit-details-marker { display: none; }
._ti_all_paragraphs_summary::marker { content: ""; }
._ti_all_paragraphs[open] > ._ti_all_paragraphs_summary {
  border-bottom: 1px solid #cbd5e1;
}
._ti_all_paragraphs_body {
  padding: 0;
}
._ti_all_paragraphs_help {
  padding: 10px 14px;
  background: #fffbeb;
  border-bottom: 1px solid #fde68a;
  font-size: 11px;
  color: #78350f;
  line-height: 1.5;
}
._ti_para_list {
  max-height: 600px;
  overflow-y: auto;
}
._ti_para_row {
  display: grid;
  grid-template-columns: 24px 48px auto auto 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 6px 14px;
  border-top: 1px solid #f1f5f9;
  font-size: 11px;
  transition: background 0.1s;
}
._ti_para_row:first-child { border-top: 0; }
._ti_para_row:hover { background: #fafbfc; }
._ti_para_row_selected { background: #fffbeb !important; }
._ti_para_row_logic { opacity: 0.7; }
._ti_para_checkbox {
  cursor: pointer;
  accent-color: #c9a227;
  width: 14px;
  height: 14px;
}
._ti_para_idx {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  color: #94a3b8;
  text-align: right;
}
._ti_para_header_chip {
  font: 800 9px/1 Inter, sans-serif;
  color: #fff;
  background: #1565c0;
  padding: 2px 6px;
  border-radius: 3px;
}
._ti_para_preview {
  color: #334155;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  min-width: 0;
}
._ti_para_assignment {
  font: 600 10px/1.3 Inter, sans-serif;
  color: #475569;
  background: #f1f5f9;
  padding: 2px 7px;
  border-radius: 3px;
  white-space: nowrap;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
}
._ti_para_assignment_manual { background: #dbeafe; color: #1e40af; }
._ti_para_assignment_none { background: #fee2e2; color: #991b1b; font-style: italic; }

._ti_sticky_action {
  position: sticky;
  bottom: 0;
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 100%);
  border-top: 2px solid #c9a227;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font: 600 12px/1.3 Inter, sans-serif;
  color: #422006;
  z-index: 10;
}
._ti_sticky_buttons {
  display: flex;
  gap: 8px;
}
._ti_row_heading {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 10px;
}
._ti_field_group {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
._ti_field_label {
  font: 800 8.5px/1 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: #94a3b8;
  padding-left: 2px;
}
._ti_input {
  padding: 6px 8px;
  font: 600 12px/1.3 Inter, sans-serif;
  color: #0f172a;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  outline: none;
  background: #fff;
  transition: border-color 0.12s, background 0.12s;
  min-width: 0;
}
._ti_input:focus { border-color: #c9a227; background: #fffbeb; }
._ti_input_number {
  font-family: ui-monospace, Consolas, monospace;
  text-align: center;
  background: #f8fafc;
}
._ti_input_number:focus { background: #fffbeb; }

._ti_row_meta {
  font-size: 10.5px;
  color: #64748b;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
._ti_meta_label {
  font: 800 8.5px/1 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: #94a3b8;
}
._ti_bookmark_name {
  font-family: ui-monospace, Consolas, monospace;
  background: #dbeafe;
  color: #1e40af;
  padding: 2px 7px;
  border-radius: 3px;
  font-size: 10.5px;
  font-weight: 600;
  border: 1px dashed #93c5fd;
}
._ti_row_meta_dim { color: #94a3b8; }
._ti_row_locate {
  margin-left: auto;
  padding: 4px 10px;
  font: 700 9.5px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #1565c0;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.12s;
}
._ti_row_locate:hover {
  background: #eff6ff;
  border-color: #1565c0;
}
